-- Phase 7 research provenance record (07-FIX6, decision D-A, ADR-0030, RSRCH-03). Generated by
-- `pnpm exec drizzle-kit generate --name research_source_records` on top of the journal
-- (position 0011, after 0010_research_job_runs), then hand-edited as 0007 was:
--   1. `IF NOT EXISTS` added to the CREATE TABLE, because drizzle-kit does not emit it and a
--      partly set-up store must never fail a service start on this file.
--
-- One row per (job run, source) whose raw note a run wrote and read back. It is the trust root
-- of "verified": a report and its raw note live in the vault and can be forged together, this
-- table cannot be reached from the vault. The view model counts a quote as evidence only when
-- the raw note it reads back hashes to `content_hash` here for the report's own run.
--
-- The columns hold ids, hashes, an https address the owner's allowlist already named, a
-- vault-relative snapshot path, the owner's short source label and an ISO instant ONLY. No
-- fetched text, remote title or model output column exists and none may be added;
-- `migration-provenance.audit.test.ts` walks the column names and the stored values.
--
-- Applied files are never renumbered, renamed or edited (ADR-0018, M-1).
CREATE TABLE IF NOT EXISTS `research_source_records` (
	`job_run_id` text NOT NULL,
	`source_id` text NOT NULL,
	`canonical_url` text NOT NULL,
	`content_hash` text NOT NULL,
	`snapshot_path` text NOT NULL,
	`label` text NOT NULL,
	`recorded_at` text NOT NULL,
	PRIMARY KEY(`job_run_id`, `source_id`)
);
